"""Generated notebook and workbench (plan §6, WP3.2; ADR 0001 decision 1).

``notebooks/study_generated.py`` is regenerated on every render:

* header "generated at revision N — do not edit";
* setup cell: ``HYPOTRAIL_READ_ONLY=1``, the read API (through
  :mod:`mlkit.study.notebook_view`, which installs the read-only guard), and
  ``RESULT_IDS`` frozen at generation, so the numbers are those of the HTML report;
* a banner cell that says whether the study moved on since generation;
* one section per plan step: question, concept (term first, then the contextual
  explanation), method, the activity source (displayed, not executed), the result,
  the interpretation, the consequence. A step without result says "Not executed yet".

Sources are produced with Marimo's own code generator
(``marimo._ast.codegen.generate_filecontents``, pinned ``marimo==0.25.1``), so an
unmodified editor save writes the same bytes back (ADR 0001 finding 5).

Preservation. A user edit is any byte difference from the hash recorded in the
manifest, ignoring only the ``__generated_with`` version stamp. The edited file is
copied byte for byte to ``study_generated.user-edits-<rev>.py`` (``-2``, ``-3`` … if
that exists; created with ``O_EXCL``), where ``<rev>`` is the revision the edited file
was generated at, then regenerated. The hash is checked again immediately before
``os.replace``: an edit saved in between (Marimo autosaves) is preserved too.

``notebooks/workbench.py`` is created once with ``O_EXCL`` and never written again. A
template bump writes ``workbench.candidate.py`` instead.

This module writes files; it refuses to run in a read-only process
(``read_only_process``). It imports neither pandas nor scikit-learn.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import uuid
from pathlib import Path
from typing import Any, Callable, Mapping

from . import guard, manifest as mf, render_html, texts
from .templates import workbench as wb_template

GENERATED = mf.ARTIFACTS['notebook']
WORKBENCH = mf.ARTIFACTS['workbench']
CANDIDATE = 'notebooks/workbench.candidate.py'
STUDY_TEMPLATE_VERSION = 1
MAX_REPLACE_ATTEMPTS = 5

_GENERATED_WITH = re.compile(rb'^__generated_with = "[^"\n]*"$', re.MULTILINE)
_TEMPLATE_VERSION = re.compile(rb'template_version = (\d+)')

# Test hook: called with the target path right before the final hash check and
# os.replace (simulates an editor autosave racing the render).
before_replace: Callable[[Path], None] | None = None


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def edit_check_sha256(data: bytes) -> str:
    """Hash used to detect user edits; only the ``__generated_with`` stamp is ignored."""
    return sha256(_GENERATED_WITH.sub(b'__generated_with = ""', data))


# --- generation -------------------------------------------------------------------------

def _codegen(header: str, cells: list[tuple[str, str]]) -> str:
    from marimo._ast.app_config import _AppConfig
    from marimo._ast.cell import CellConfig
    from marimo._ast.codegen import generate_filecontents

    return generate_filecontents([code for _, code in cells], [name for name, _ in cells],
                                 [CellConfig() for _ in cells], config=_AppConfig(),
                                 header_comments=header)


def result_ids(view: Mapping) -> dict[str, str]:
    """Slot -> result id of every citable result (current, integrity ok)."""
    return {slot: item['result_id'] for slot, item in sorted(view['results'].items())
            if item['current'] and item['integrity'] == 'ok'}


def _md_cell(text: str) -> str:
    """A Markdown cell in the triple-quoted form Marimo's codegen keeps."""
    if '"""' in text or '\\' in text or text.endswith('"'):
        return f'mo.md({text!r})'
    return 'mo.md(\n    r"""\n' + text + '\n"""\n)'


def _step_markdown(index: int, step: Mapping, content: Mapping, pending: bool) -> str:
    lines = [f'## {index}. {step["title"]}', '', f'**Question.** {step["question"]}']
    term = texts.glossary(content.get('concept')) if content.get('concept') else None
    if term:
        lines += ['', f'**{term["term"]}.** {term["definition"]}']
    if content.get('method'):
        lines += ['', f'**Method.** {content["method"]}']
    if pending:
        lines += ['', f'_{texts.load("steps")["pending"]}_']
    return '\n'.join(lines)


def generate_study_source(view: Mapping) -> str:
    revision = view['revision']
    rids = result_ids(view)
    header = (f'# Generated by Hypotrail at revision {revision}. Do not edit.\n'
              '# A modified copy is preserved as study_generated.user-edits-<rev>.py on the next '
              'render; write your notes in workbench.py.\n'
              f'# template_version = {STUDY_TEMPLATE_VERSION}')
    setup = (wb_template.SETUP
             + f'\nGENERATED_REVISION = {revision!r}\n'
             + f'RESULT_IDS = {json.dumps(rids, sort_keys=True, indent=4)}')
    cells: list[tuple[str, str]] = [
        ('setup', setup),
        ('load_study', 'study = nv.open_study(STUDY_DIR)\ncited = nv.citer(study, RESULT_IDS)'),
        ('banner', 'mo.Html(nv.banner_html(study, GENERATED_REVISION, RESULT_IDS))'),
    ]
    for index, step in enumerate(view['plan'], start=1):
        content = texts.step(step['id'])
        slots = render_html.slots_of_step(step['id'], view['results'])
        has_result = any(s in rids for s in slots)
        pending = not has_result and not step['decision']
        cells.append((f'step_{step["id"]}_text',
                      _md_cell(_step_markdown(index, step, content, pending))))
        if pending:
            continue
        items = [f'mo.Html(nv.step_html(cited, RESULT_IDS, {slots!r}, '
                 f'{content.get("context", "")!r}, {content.get("interpretation", "")!r}))']
        if step['decision']:
            items.append(f'mo.Html(nv.decision_html(study, {step["decision"]!r}))')
        if has_result:
            items.append(f'nv.source_block(study, RESULT_IDS, {[s for s in slots if s in rids]!r})')
        if content.get('consequence'):
            items.append(f'mo.md({("**Consequence.** " + content["consequence"])!r})')
        body = 'mo.vstack(\n    [\n' + ''.join(f'        {i},\n' for i in items) + '    ]\n)'
        cells.append((f'step_{step["id"]}', body))
    return _codegen(header, cells)


def generate_workbench_source(template_version: int = wb_template.TEMPLATE_VERSION) -> str:
    return _codegen(wb_template.header(template_version), wb_template.cells(template_version))


# --- writing ----------------------------------------------------------------------------

def _create_exclusive(path: Path, data: bytes) -> None:
    guard.assert_writable()
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    with os.fdopen(fd, 'wb') as handle:
        handle.write(data)
        handle.flush()
        os.fsync(handle.fileno())


def _preserve(study: Path, data: bytes, revision: Any) -> str:
    """Copy ``data`` to ``study_generated.user-edits-<rev>[-n].py``; return its path."""
    folder = study / 'notebooks'
    base = f'study_generated.user-edits-{revision if revision is not None else "unknown"}'
    counter = 1
    while True:
        name = f'{base}.py' if counter == 1 else f'{base}-{counter}.py'
        try:
            _create_exclusive(folder / name, data)
            return f'notebooks/{name}'
        except FileExistsError:
            counter += 1


def _is_edit(data: bytes, record: Mapping | None) -> bool:
    if record is None or not record.get('edit_check_sha256'):
        return True       # no record: a file we did not write, or a lost manifest
    return edit_check_sha256(data) != record['edit_check_sha256']


def _write_generated(study: Path, data: bytes, record: Mapping | None) -> list[str]:
    """Write the generated notebook, preserving every user edit first."""
    guard.assert_writable()
    path = study / GENERATED
    path.parent.mkdir(parents=True, exist_ok=True)
    preserved: list[str] = []
    expected = edit_check_sha256(data)
    known = dict(record or {})
    temp = path.with_name(f'.{path.name}.{os.getpid()}.{uuid.uuid4().hex[:8]}.tmp')
    try:
        with open(temp, 'wb') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        for _ in range(MAX_REPLACE_ATTEMPTS):
            current = path.read_bytes() if path.exists() else None
            if current is not None and _is_edit(current, known) \
                    and edit_check_sha256(current) != expected:
                preserved.append(_preserve(study, current, known.get('revision')))
            if before_replace is not None:
                before_replace(path)
            # Re-check immediately before the replace: an autosave in between is kept.
            again = path.read_bytes() if path.exists() else None
            if again == current:
                os.replace(temp, path)
                return preserved
            known = {'edit_check_sha256': edit_check_sha256(current) if current else None,
                     'revision': known.get('revision')}
        raise OSError('the generated notebook kept changing during the render')
    finally:
        temp.unlink(missing_ok=True)


def _file_template_version(data: bytes) -> int | None:
    m = _TEMPLATE_VERSION.search(data.split(b'\n\n', 1)[0])
    return int(m.group(1)) if m else None


def render(study_dir, view: Mapping, manifest: Mapping, *,
           workbench_template_version: int = wb_template.TEMPLATE_VERSION) -> dict:
    """Regenerate the notebook and keep the workbench; return the two manifest items."""
    guard.assert_writable()
    study = Path(study_dir)
    revision = view['revision']

    record = mf.item(manifest, 'notebook', kind='marimo_notebook')
    data = generate_study_source(view).encode('utf-8')
    preserved = _write_generated(study, data, manifest.get('artifacts', {}).get('notebook'))
    record.update(revision=revision, status='ok', consumed=sorted(set(result_ids(view).values())),
                  sha256=sha256(data), edit_check_sha256=edit_check_sha256(data), generated=True,
                  template_version=STUDY_TEMPLATE_VERSION, error=None, last_ok_revision=revision,
                  user_edits_preserved=list(record.get('user_edits_preserved') or []) + preserved,
                  candidate=None)

    workbench = study / WORKBENCH
    wb = mf.item(manifest, 'workbench', kind='marimo_notebook', generated=False)
    wb.update(status='ok', generated=False, error=None, consumed=[])
    if not workbench.exists():
        wb_data = generate_workbench_source(workbench_template_version).encode('utf-8')
        _create_exclusive(workbench, wb_data)
        wb.update(revision=revision, sha256=sha256(wb_data), sha256_at_creation=sha256(wb_data),
                  template_version=workbench_template_version, last_ok_revision=revision,
                  candidate=None)
    else:
        if wb.get('template_version') is None:
            wb['template_version'] = _file_template_version(workbench.read_bytes())
        if wb.get('revision') is None:
            wb['revision'] = revision
        if workbench_template_version > (wb.get('template_version') or 0):
            cand_path = study / CANDIDATE
            cand = generate_workbench_source(workbench_template_version).encode('utf-8')
            previous = (wb.get('candidate') or {}).get('sha256')
            if cand_path.exists() and sha256(cand_path.read_bytes()) not in (previous, sha256(cand)):
                # the user edited an earlier candidate: keep it, do not overwrite
                wb['candidate'] = dict(wb.get('candidate') or {}, kept_user_copy=True)
            else:
                from .store import atomic_write

                atomic_write(cand_path, cand)
                wb['candidate'] = {'path': CANDIDATE, 'template_version': workbench_template_version,
                                   'sha256': sha256(cand)}
    return {'notebook': record, 'workbench': wb, 'preserved': preserved}
